"use strict";export class ModuleReadiness{constructor(){this.requiredModules=new Set,this.loadedModules=new Set}require(e){return this.requiredModules.add(e),this}isReady(e){return this.loadedModules.has(e)}async waitFor(e,o=5e3){const r=Date.now();for(;Date.now()-r<o;){if(this.isReady(e))return!0;await new Promise(e=>setTimeout(e,100))}throw new Error(`Module ${e} not ready after ${o}ms`)}async waitForAll(e=5e3){const o=Date.now(),r=Array.from(this.requiredModules);for(;Date.now()-o<e;){if(r.every(e=>this.isReady(e)))return!0;await new Promise(e=>setTimeout(e,100))}const s=r.filter(e=>!this.isReady(e));throw new Error(`Modules not ready after ${e}ms: ${s.join(", ")}`)}markReady(e){this.loadedModules.add(e),console.log(`✅ Module ready: ${e}`)}}window.moduleReadiness=new ModuleReadiness;